function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function num(v){const n=Number(v);return Number.isFinite(n)?n:0;}
function fmtNum(v,d=1){return new Intl.NumberFormat('id-ID',{maximumFractionDigits:d}).format(num(v));}
function fmtRp(v){return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(num(v));}
function fmtDate(v){if(!v)return '-';const d=new Date(v);if(Number.isNaN(d.getTime()))return esc(v);return new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',year:'numeric'}).format(d);}
function statusColor(s){const x=String(s||'').toUpperCase();if(['PAID','VERIFIED','APPROVED','PASS','PASSED','DONE','CLOSED','RELEASED','RECEIVED'].some(k=>x.includes(k)))return 'green';if(['REJECT','NG','CRITICAL','DELAY','CANCEL','OVER'].some(k=>x.includes(k)))return 'red';if(['PENDING','SUBMITTED','WAITING','PROCESS','PRICING','HOLD','CONDITIONAL','OPEN'].some(k=>x.includes(k)))return 'orange';if(['CLIENT','QS','ADMIN','ORDERED'].some(k=>x.includes(k)))return 'purple';return 'gray';}
function statusPill(s){return `<span class="pill ${statusColor(s)}">${esc(s||'-')}</span>`;}
function kpi(label,value,color=''){return `<div class="kpi ${color}"><div class="label">${esc(label)}</div><div class="value">${value}</div></div>`;}
function employeeName(id){const e=state.employees.find(x=>x.id===id);return e?e.name:(id||'-');}
function projectName(id){const p=state.projects.find(x=>x.id===id);return p?(p.data.name||p.id):(id||'-');}
function canView(v){return Boolean(state.access?.views?.includes(v));}
function canCollection(c,a='read'){return Boolean(state.access?.collections?.[c]?.[a]);}
function cap(k){return Boolean(state.access?.capabilities?.[k]);}
function assignedProjectScope(){return ['project_manager','pelaksana_lapangan'].includes(state.access?.roleKey);}

async function api(path,{method='GET',body,headers={}}={}){
  const opts={method,headers:{...headers},credentials:'include'};
  if(body instanceof FormData) opts.body=body;
  else if(body!==undefined){opts.headers['content-type']='application/json';opts.body=JSON.stringify(body);}
  const res=await fetch(path,opts);let data=null;const ct=res.headers.get('content-type')||'';
  if(ct.includes('application/json'))data=await res.json();else data=await res.text();
  if(!res.ok){const msg=data?.message||data?.error||`HTTP ${res.status}`;throw new Error(msg);}
  return data;
}
function toast(message,type=''){const el=document.createElement('div');el.className=`toast ${type==='err'?'err':''}`;el.textContent=message;$('#toastArea').append(el);setTimeout(()=>el.remove(),3800);}

async function init(){
  bindShell();
  try{const me=await api('/api/auth/me');await enterApp(me);}catch{showLogin();}
}
function bindShell(){
  $('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginError').textContent='';try{const r=await api('/api/auth/login',{method:'POST',body:{username:$('#loginUsername').value,password:$('#loginPassword').value,remember:$('#loginRemember').checked}});const me=await api('/api/auth/me');await enterApp(me);}catch(err){$('#loginError').textContent=err.message;}};
  $('#logoutBtn').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST'});}catch{} location.reload();};
  $('#changePasswordBtn').onclick=openPasswordForm;
  $('#refreshBtn').onclick=fullRefresh;
  $('#burger').onclick=()=>$('#sidebar').classList.toggle('open');
  $('#globalProjectFilter').onchange=async e=>{state.selectedProjectId=e.target.value;state.cache.clear();await renderView();};
  $('#modalClose').onclick=closeModal;$('#modalCancel').onclick=closeModal;$('#modalSave').onclick=()=>$('#modalForm').requestSubmit();
  $('#confirmCancel').onclick=()=>resolveConfirm(false);$('#confirmOk').onclick=()=>resolveConfirm(true);
  $$('#nav [data-view]').forEach(btn=>btn.onclick=()=>setView(btn.dataset.view));
}
function showLogin(){$('#loginScreen').classList.remove('hidden');$('#app').classList.add('hidden');}
async function enterApp(me){
  state.user=me.user;state.access=me.access;$('#loginScreen').classList.add('hidden');$('#app').classList.remove('hidden');
  $('#userName').textContent=state.user.name||state.user.username;$('#userRole').textContent=(state.access.roleLabel||state.user.role)+(assignedProjectScope()?' • Proyek ditugaskan saja':'');
  applyRoleNavigation();await fullRefresh();
  const preferred=canView('dashboard')?'dashboard':(state.access.views?.[0]||'projects');setView(preferred);
}
function applyRoleNavigation(){
  $$('#nav [data-view]').forEach(b=>b.classList.toggle('hidden',!canView(b.dataset.view)));
}
async function fullRefresh(){
  state.cache.clear();
  const [p,e,d]=await Promise.all([api('/api/records/projects'),api('/api/employees'),api('/api/dashboard')]);
  state.projects=p.rows||[];state.employees=e.employees||[];state.dashboard=d;populateProjectFilter();await renderView();
}
function populateProjectFilter(){const sel=$('#globalProjectFilter');const keep=state.selectedProjectId;const allLabel=assignedProjectScope()?'Semua proyek yang saya tangani':'Semua proyek';sel.innerHTML=`<option value="">${allLabel}</option>`+state.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.data.name||p.id)}</option>`).join('');if(state.projects.some(p=>p.id===keep))sel.value=keep;else{state.selectedProjectId='';sel.value='';}}
function setView(view){if(!canView(view)){toast('Menu ini tidak tersedia untuk role Anda.','err');return;}state.view=view;$$('#nav .nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#sidebar').classList.remove('open');renderView();}
async function renderView(){const meta=TITLES[state.view]||['KENDALI',''];$('#pageTitle').textContent=meta[0];$('#pageSubtitle').textContent=meta[1];$('#content').innerHTML='<div class="loading"><div class="spinner"></div>Memuat…</div>';try{const fn={dashboard:renderDashboard,projects:renderProjects,finance:renderFinance,fund_requests:renderFundRequests,progress:renderProgress,opname:renderOpname,qc:renderQc,cco:renderCco,procurement:renderProcurement,documents:renderDocuments,flow:renderFlow,closeout:renderCloseout,employees:renderEmployees,master:renderMaster,audit:renderAudit}[state.view];if(fn)await fn();}catch(err){$('#content').innerHTML=`<div class="card"><div class="card-body"><b>Terjadi kendala</b><p class="muted">${esc(err.message)}</p></div></div>`;}}
async function loadCollection(c,projectScoped=false){const key=`${c}|${projectScoped?state.selectedProjectId:''}`;if(state.cache.has(key))return state.cache.get(key);const q=projectScoped&&state.selectedProjectId?`?projectId=${encodeURIComponent(state.selectedProjectId)}`:'';const r=await api(`/api/records/${c}${q}`);const rows=r.rows||[];state.cache.set(key,rows);return rows;}

function progressChart(series=[]){
  if(!series.length)return `<div class="empty">Belum ada progress. Input Progress Harian/Mingguan untuk menampilkan grafik.</div>`;
  const w=560,h=170,padL=28,padR=10,padT=12,padB=26,iw=w-padL-padR,ih=h-padT-padB;
  const pts=series.slice(-30);const x=i=>padL+(pts.length===1?iw/2:(i/(pts.length-1))*iw);const y=v=>padT+ih-(Math.max(0,Math.min(100,num(v)))/100)*ih;
  const actual=pts.map((p,i)=>`${x(i)},${y(p.actual)}`).join(' ');const plan=pts.map((p,i)=>`${x(i)},${y(p.plan)}`).join(' ');
  const grid=[0,25,50,75,100].map(v=>`<line class="chart-grid" x1="${padL}" y1="${y(v)}" x2="${w-padR}" y2="${y(v)}"/><text class="chart-label" x="2" y="${y(v)+3}">${v}%</text>`).join('');
  return `<div class="chart-wrap"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Grafik progress rencana dan aktual">${grid}<polyline class="chart-plan" points="${plan}"/><polyline class="chart-actual" points="${actual}"/>${pts.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.actual)}" r="2.8" fill="#175cd3"/>`).join('')}<text class="chart-label" x="${padL}" y="${h-5}">${esc(pts[0].date)}</text><text class="chart-label" text-anchor="end" x="${w-padR}" y="${h-5}">${esc(pts.at(-1).date)}</text></svg><div class="chart-legend"><span><i class="legend-line"></i>Aktual/Realisasi</span><span><i class="legend-line plan"></i>Rencana</span></div></div>`;
}

async function renderDashboard(){
  state.dashboard=await api('/api/dashboard');const all=state.dashboard.projects||[];const rows=state.selectedProjectId?all.filter(x=>x.id===state.selectedProjectId):all;const t=state.dashboard.totals||{};const financeVisible=canView('finance');
  const baseKpis=`<div class="kpis">${kpi('Proyek Aktif',fmtNum(rows.filter(x=>x.evaluatedStatus!=='CLOSED').length,0),'blue')}${kpi('Rata-rata Progress',`${fmtNum(rows.length?rows.reduce((s,x)=>s+num(x.progress),0)/rows.length:0)}%`,'purple')}${kpi('Proyek Delay',fmtNum(rows.filter(x=>String(x.scheduleStatus).toUpperCase()==='DELAY').length,0),'red')}${kpi('QC/Defect Open',fmtNum(rows.reduce((s,x)=>s+num(x.openQc)+num(x.openDefects),0),0),'orange')}${kpi('CCO Pending',fmtNum(rows.reduce((s,x)=>s+num(x.pendingCco),0),0),'orange')}${financeVisible?kpi('Cash In',fmtRp(rows.reduce((s,x)=>s+num(x.income),0)),'green')+kpi('Cash Out',fmtRp(rows.reduce((s,x)=>s+num(x.expense),0)),'red')+kpi('Net Cash',fmtRp(rows.reduce((s,x)=>s+num(x.netCash),0)),'blue'):''}</div>`;
  const cards=rows.map(r=>{const p=state.projects.find(x=>x.id===r.id)?.data||{};return `<div class="project-card"><div class="project-card-head"><div><h3>${esc(r.name)}</h3><div class="project-meta">PM: ${esc(employeeName(p.pmUserId))}<br>Pelaksana: ${esc(employeeName(p.pelaksanaUserId))}</div></div><div>${statusPill(r.evaluatedStatus)}<div class="tiny muted" style="margin-top:5px">${fmtNum(r.progress)}%</div></div></div>${progressChart(r.progressSeries||[])}${financeVisible?`<div class="project-meta">Kontrak ${fmtRp(r.contract)} • HPP ${fmtRp(r.budget)} • Cash In ${fmtRp(r.income)} • Cash Out ${fmtRp(r.expense)}</div>`:`<div class="project-meta">Schedule: ${esc(r.scheduleStatus)} • QC open: ${fmtNum(r.openQc,0)} • Defect open: ${fmtNum(r.openDefects,0)}</div>`}</div>`;}).join('')||'<div class="card"><div class="empty">Belum ada proyek.</div></div>';
  $('#content').innerHTML=baseKpis+`<div class="project-grid">${cards}</div>`+dashboardTable(rows,financeVisible);
}
function dashboardTable(rows,financeVisible){return `<div class="card"><div class="card-head"><div><h3>Kontrol Semua Proyek</h3><p>Progress berasal dari input terbaru. Status proyek dievaluasi melalui gate.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Proyek</th><th>Progress</th><th>Schedule</th><th>QC</th><th>CCO</th>${financeVisible?'<th>Kontrak</th><th>Cash In</th><th>Cash Out</th><th>Net Cash</th>':''}<th>Status</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${fmtNum(r.progress)}%</td><td>${statusPill(r.scheduleStatus)}</td><td>${fmtNum(num(r.openQc)+num(r.openDefects),0)}</td><td>${fmtNum(r.pendingCco,0)}</td>${financeVisible?`<td class="num">${fmtRp(r.contract)}</td><td class="num">${fmtRp(r.income)}</td><td class="num">${fmtRp(r.expense)}</td><td class="num">${fmtRp(r.netCash)}</td>`:''}<td>${statusPill(r.evaluatedStatus)}</td></tr>`).join('')||'<tr><td colspan="10" class="empty">Belum ada data.</td></tr>'}</tbody></table></div></div>`;}

async function renderProjects(){
  const rows=await loadCollection('projects');
  const scope=assignedProjectScope()?'<div class="notice blue"><b>Akses proyek dibatasi:</b> akun Project Manager/Pelaksana hanya dapat melihat proyek yang menempatkan akun tersebut sebagai PIC pada master proyek. Pembatasan ini berlaku di tampilan dan API.</div>':'';
  $('#content').innerHTML=scope+`<div class="card"><div class="card-head"><div><h3>Daftar Proyek</h3><p>Project Manager, Pelaksana, QS, QC, dan Admin dipilih dari master karyawan.</p></div>${canCollection('projects','create')?'<div class="card-actions"><button class="btn primary" data-add="projects">+ Tambah Proyek</button></div>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Proyek</th><th>Client</th><th>PM</th><th>Pelaksana</th><th>QS</th><th>QC</th><th>Kontrak</th><th>HPP</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.data.name||r.id)}</b><div class="tiny muted">${esc(r.data.location||'')}</div></td><td>${esc(r.data.client||'-')}</td><td>${esc(employeeName(r.data.pmUserId))}</td><td>${esc(employeeName(r.data.pelaksanaUserId))}</td><td>${esc(employeeName(r.data.qsUserId))}</td><td>${esc(employeeName(r.data.qcUserId))}</td><td class="num">${fmtRp(r.data.contractValue)}</td><td class="num">${fmtRp(r.data.budget)}</td><td>${statusPill(r.data.status||'SETUP')}</td><td class="actions">${canCollection('projects','update')?`<button class="btn small" data-edit="projects" data-id="${esc(r.id)}">Edit</button>`:''}${canCollection('projects','delete')?`<button class="btn small danger" data-delete="projects" data-id="${esc(r.id)}">Hapus</button>`:''}</td></tr>`).join('')||'<tr><td colspan="10" class="empty">Belum ada proyek yang ditugaskan ke akun ini.</td></tr>'}</tbody></table></div></div>`;
  bindCrudActions();
}

async function renderFinance(){
  const scope=Boolean(state.selectedProjectId);const [budget,ar,cin,ap,cout]=await Promise.all(['project_budget','receivables','cash_in','payables','cash_out'].map(c=>loadCollection(c,scope)));
  const explanation=`<div class="info-grid"><div class="info-card"><span class="tag auto">Otomatis dari Proyek</span><h4>Nilai Kontrak & HPP</h4><p>Nilai kontrak dan HPP di master proyek langsung dipakai dashboard. HPP proyek juga membuat/update baseline Budget Proyek otomatis. Ini bukan transaksi kas.</p></div><div class="info-card"><span class="tag manual">Finance</span><h4>Piutang & Cash In</h4><p>Kontrak tidak otomatis dianggap uang masuk. Finance membuat tagihan/piutang sesuai termin. Saat uang benar-benar diterima, input Cash In. Jika Cash In dikaitkan ke ID piutang, paid amount ikut diperbarui.</p></div><div class="info-card"><span class="tag auto">Dari Karyawan</span><h4>Payment Request → Cash Out</h4><p>Karyawan mengajukan kebutuhan di menu Pengajuan Dana. Setelah approved dan Finance menekan Bayar, sistem otomatis membuat Cash Out.</p></div><div class="info-card"><span class="tag auto">Dari Procurement</span><h4>PO/SPK → Hutang</h4><p>PO/SPK yang berstatus Approved/Ordered/Partial otomatis membentuk Hutang/Outstanding proyek. Cash Out tetap hanya muncul saat pembayaran benar-benar dicatat.</p></div></div>`;
  $('#content').innerHTML=explanation+genericTable('project_budget',budget,'Budget / HPP Proyek','Baseline biaya dan cost code.')+genericTable('receivables',ar,'Piutang Client','Tagihan yang belum seluruhnya diterima.')+genericTable('cash_in',cin,'Pemasukan / Cash In','Hanya uang yang benar-benar diterima/terverifikasi.')+genericTable('payables',ap,'Hutang / Outstanding','Komitmen yang masih harus dibayar.')+genericTable('cash_out',cout,'Pengeluaran / Cash Out','Pengeluaran yang benar-benar sudah dibayar.');bindCrudActions();
}

async function renderFundRequests(){
  const rows=await loadCollection('payment_requests',Boolean(state.selectedProjectId));
  $('#content').innerHTML=`<div class="notice blue"><b>Alur:</b> Karyawan membuat DRAFT → Submit → PENDING → Finance/Manajemen Approve/Reject → Finance Bayar → sistem otomatis membuat Cash Out.</div><div class="card"><div class="card-head"><div><h3>Pengajuan Dana Karyawan</h3><p>Untuk material, upah, operasional, alat, transport, atau kebutuhan proyek lainnya.</p></div>${canCollection('payment_requests','create')?'<div class="card-actions"><button class="btn primary" data-add="payment_requests">+ Buat Pengajuan</button></div>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Proyek</th><th>Pengaju</th><th>Kebutuhan</th><th>Nominal</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${fmtDate(r.data.date)}</td><td>${esc(projectName(r.data.projectId))}</td><td>${esc(employeeName(r.data.requesterUserId))}</td><td>${esc(r.data.description||'-')}<div class="tiny muted">${esc(r.data.category||'')}</div></td><td class="num">${fmtRp(r.data.amount)}</td><td>${statusPill(r.data.status||'DRAFT')}</td><td class="actions">${fundButtons(r)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Belum ada pengajuan.</td></tr>'}</tbody></table></div></div>`;
  bindCrudActions();bindWorkflowButtons();
}
function fundButtons(r){const s=String(r.data.status||'DRAFT').toUpperCase();let x='';if(canCollection('payment_requests','update')&&['DRAFT','REJECTED'].includes(s))x+=`<button class="btn small" data-edit="payment_requests" data-id="${esc(r.id)}">Edit</button>`;if(['DRAFT','REJECTED'].includes(s))x+=`<button class="btn small primary" data-fund-action="submit" data-id="${esc(r.id)}">Submit</button>`;if(cap('financeApprove')&&s==='PENDING')x+=`<button class="btn small success" data-fund-action="approve" data-id="${esc(r.id)}">Approve</button><button class="btn small danger" data-fund-action="reject" data-id="${esc(r.id)}">Reject</button>`;if(cap('financePay')&&s==='APPROVED')x+=`<button class="btn small accent" data-fund-action="pay" data-id="${esc(r.id)}">Bayar</button>`;return x||'-';}

async function renderProgress(){const scope=Boolean(state.selectedProjectId);const [daily,weekly,schedule,milestones,issues]=await Promise.all(['daily_progress','weekly_progress','schedule','milestones','issues'].map(c=>loadCollection(c,scope)));$('#content').innerHTML=`<div class="notice green">Grafik Dashboard menggunakan nilai <b>Progress Rencana</b> dan <b>Progress Aktual/Realisasi</b> dari input Harian/Mingguan berdasarkan tanggal.</div>${genericTable('daily_progress',daily,'Progress Harian','Input aktual lapangan setiap hari.')}${genericTable('weekly_progress',weekly,'Progress Mingguan','Rekap mingguan dan tindak lanjut.')}${genericTable('schedule',schedule,'Schedule / Kurva-S','Aktivitas, bobot, target waktu, dan aktual.')}${genericTable('milestones',milestones,'Milestone','Target penting proyek.')}${genericTable('issues',issues,'Masalah & Corrective Action','Masalah → Dampak → Penyebab → Pilihan → Keputusan → PIC → Deadline.')}`;bindCrudActions();}

async function renderOpname(){const rows=await loadCollection('opname',Boolean(state.selectedProjectId));$('#content').innerHTML=`<div class="info-grid"><div class="info-card"><span class="tag">QS</span><h4>QS = Quantity Surveyor</h4><p>QS memeriksa volume pekerjaan yang benar-benar terpasang di lapangan, membandingkannya dengan RAB/gambar, menyusun atau memverifikasi opname, dan menjadi dasar berita acara/termin pembayaran.</p></div><div class="info-card"><span class="tag auto">Kontrol</span><h4>Opname bukan hanya laporan pengawas</h4><p>Data lapangan dari Pelaksana menjadi bahan. Volume final yang dipakai untuk komersial harus melalui verifikasi QS dan bukti/BA dapat di-upload pada form opname.</p></div></div>${genericTable('opname',rows,'Opname Lapangan / QS','Volume kontrak, volume periode, volume terverifikasi QS, nilai, dan BA.')}`;bindCrudActions();}

async function renderQc(){
  if(!state.selectedProjectId){$('#content').innerHTML=noProjectPrompt('Pilih satu proyek pada filter atas untuk membuka QC Dashboard lengkap.');bindGotoProjects();return;}
  const [items,inspections,defects]=await Promise.all(['qc_work_items','qc_inspections','defects'].map(c=>loadCollection(c,true)));
  const latest=new Map(),count=new Map();for(const r of inspections){const k=r.data.workItemId||r.data.item;count.set(k,(count.get(k)||0)+1);const stamp=String(r.data.date||r.updated_at||'');if(!latest.has(k)||stamp>latest.get(k).stamp)latest.set(k,{stamp,row:r});}
  const passed=items.filter(i=>String(latest.get(i.id)?.row?.data?.result||'').toUpperCase()==='PASS').length;const follow=items.filter(i=>['NG','CONDITIONAL'].includes(String(latest.get(i.id)?.row?.data?.result||'').toUpperCase())).length;const uninspected=items.filter(i=>!latest.has(i.id)).length;const openDef=defects.filter(d=>String(d.data.status||'').toUpperCase()!=='CLOSED').length;
  $('#content').innerHTML=`<div class="notice blue"><b>QC Dashboard:</b> sinkronkan item dari RAB agar seluruh pekerjaan masuk checklist. Setiap inspeksi wajib upload bukti. Hasil NG/CONDITIONAL otomatis membuka defect; inspeksi ulang PASS menutup defect item tersebut.</div><div class="qc-grid"><div class="qc-stat"><b>${items.length}</b><span>Total item pekerjaan</span></div><div class="qc-stat"><b>${passed}</b><span>Latest PASS</span></div><div class="qc-stat"><b>${follow}</b><span>Perlu tindak lanjut</span></div><div class="qc-stat"><b>${uninspected}</b><span>Belum pernah inspeksi</span></div><div class="qc-stat"><b>${openDef}</b><span>Defect open</span></div></div><div class="card"><div class="card-head"><div><h3>Checklist Semua Pekerjaan</h3><p>Sumber utama dapat disinkronkan dari RAB proyek.</p></div><div class="card-actions">${cap('qcSyncRab')?'<button class="btn ghost" id="qcSyncRab">↻ Sinkron dari RAB</button>':''}${canCollection('qc_work_items','create')?'<button class="btn primary" data-add="qc_work_items">+ Item Manual</button>':''}</div></div><div class="table-wrap"><table class="table"><thead><tr><th>Kode</th><th>Item Pekerjaan</th><th>Kategori</th><th>Inspeksi</th><th>Hasil Terakhir</th><th>Tanggal</th><th>Aksi</th></tr></thead><tbody>${items.map(i=>{const l=latest.get(i.id)?.row;return `<tr><td>${esc(i.data.code||'-')}</td><td class="work-item"><b>${esc(i.data.item||'-')}</b></td><td>${esc(i.data.category||'-')}</td><td>${fmtNum(count.get(i.id)||0,0)}x</td><td>${l?statusPill(l.data.result):statusPill('BELUM INSPEKSI')}</td><td>${l?fmtDate(l.data.date):'-'}</td><td class="actions">${cap('qcInspect')?`<button class="btn small primary" data-qc-inspect="${esc(i.id)}">Inspeksi</button>`:''}${canCollection('qc_work_items','update')?`<button class="btn small" data-edit="qc_work_items" data-id="${esc(i.id)}">Edit</button>`:''}</td></tr>`;}).join('')||'<tr><td colspan="7" class="empty">Belum ada item. Klik Sinkron dari RAB atau tambah manual.</td></tr>'}</tbody></table></div></div>${genericTable('defects',defects,'Defect & Corrective Action','Temuan yang harus diperbaiki lalu di-inspeksi ulang.')}`;
  bindCrudActions();if($('#qcSyncRab'))$('#qcSyncRab').onclick=async()=>{const r=await api('/api/qc/sync-rab',{method:'POST',body:{projectId:state.selectedProjectId}});toast(`${r.created} item baru dibuat dari ${r.found} item yang terbaca di RAB.`);state.cache.clear();await renderQc();};$$('[data-qc-inspect]').forEach(b=>b.onclick=()=>openQcInspection(b.dataset.qcInspect));
}
function openQcInspection(workItemId){const item=state.cache.get(`qc_work_items|${state.selectedProjectId}`)?.find(x=>x.id===workItemId);const html=`<div class="form-grid"><label>Item Pekerjaan<input value="${esc(item?.data?.item||workItemId)}" disabled></label><label>Tanggal<input type="date" name="date" value="${new Date().toISOString().slice(0,10)}" required></label><label>Hasil<select name="result" required><option value="PASS">PASS</option><option value="NG">NG</option><option value="CONDITIONAL">CONDITIONAL</option></select></label>${fieldHtml(employeeField('qcUserId','QC Inspector',['qc'],true),state.user.id)}<label class="span-2">Catatan / Temuan<textarea name="notes"></textarea></label><label class="span-2">Bukti Foto / Dokumen <span class="field-help">WAJIB setiap kali inspeksi.</span><input type="file" name="file" accept="image/*,.pdf" required></label></div>`;openModal('QC Inspection','Setiap inspeksi menjadi log baru; bukti lama tidak ditimpa.',html,async form=>{const fd=new FormData();fd.append('projectId',state.selectedProjectId);fd.append('workItemId',workItemId);for(const k of ['date','result','qcUserId','notes'])fd.append(k,form.elements[k].value);fd.append('file',form.elements.file.files[0]);await api('/api/qc/inspect',{method:'POST',body:fd});toast('QC Inspection tersimpan.');state.cache.clear();await renderQc();});}

const CCO_FLOW=[['DRAFT','Pelaksana Draft'],['SUBMITTED_TO_ADMIN','Admin Review'],['SENT_TO_QS','Dikirim ke QS'],['QS_PRICING','QS Buat RAB'],['RAB_READY','RAB Siap'],['SENT_TO_CLIENT','Admin ke Client'],['CLIENT_APPROVED','Client Setuju'],['ADDENDUM_PROCESS','Addendum'],['CLOSED','Closed']];
async function renderCco(){const rows=await loadCollection('cco',Boolean(state.selectedProjectId));$('#content').innerHTML=`<div class="flow-strip">${CCO_FLOW.map(([c,l])=>`<div class="flow-step"><b>${esc(l)}</b>${esc(c)}</div>`).join('')}</div><div class="notice"><b>Alur dikunci:</b> Pelaksana/PM mengajukan → Admin meneruskan ke QS → QS menyusun RAB CCO → Admin mengirim ke client → keputusan client → Addendum → Closed. CCO >10% terhadap RAB wajib approval eskalasi SOP/SP sebelum dikirim ke client.</div><div class="card"><div class="card-head"><div><h3>Register CCO / Addendum</h3><p>Status hanya berpindah melalui tombol workflow, bukan edit manual.</p></div>${canCollection('cco','create')?'<div class="card-actions"><button class="btn primary" data-add="cco">+ Ajukan CCO</button></div>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Proyek</th><th>Perubahan</th><th>Pengaju</th><th>Nilai RAB CCO</th><th>% RAB</th><th>Eskalasi</th><th>Tahap</th><th>Aksi</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${fmtDate(r.data.date)}</td><td>${esc(projectName(r.data.projectId))}</td><td><b>${esc(r.data.title||'-')}</b><div class="tiny muted">${esc(r.data.reason||'')}</div></td><td>${esc(employeeName(r.data.requestedByUserId))}</td><td class="num">${r.data.amount?fmtRp(r.data.amount):'-'}</td><td>${r.data.percentOfRab?fmtNum(r.data.percentOfRab)+'%':'-'}</td><td>${statusPill(r.data.escalationLevel||'BELUM DINILAI')}</td><td>${statusPill(r.data.status||'DRAFT')}</td><td class="actions">${ccoButtons(r)}</td></tr>`).join('')||'<tr><td colspan="9" class="empty">Belum ada CCO.</td></tr>'}</tbody></table></div></div>`;bindCrudActions();bindWorkflowButtons();}
function ccoButtons(r){const s=String(r.data.status||'DRAFT').toUpperCase();let x='';if(canCollection('cco','update')&&['DRAFT','RETURNED_TO_FIELD','QS_PRICING'].includes(s))x+=`<button class="btn small" data-edit="cco" data-id="${esc(r.id)}">Edit</button>`;if(cap('ccoFieldSubmit')&&['DRAFT','RETURNED_TO_FIELD'].includes(s))x+=`<button class="btn small primary" data-cco-action="submit-admin" data-id="${esc(r.id)}">Ajukan ke Admin</button>`;if(cap('ccoAdmin')&&s==='SUBMITTED_TO_ADMIN')x+=`<button class="btn small primary" data-cco-action="send-qs" data-id="${esc(r.id)}">Teruskan ke QS</button>`;if(cap('ccoQs')&&s==='SENT_TO_QS')x+=`<button class="btn small" data-cco-action="start-pricing" data-id="${esc(r.id)}">Mulai RAB</button>`;if(cap('ccoQs')&&['SENT_TO_QS','QS_PRICING'].includes(s))x+=`<button class="btn small accent" data-cco-price="${esc(r.id)}">Selesaikan RAB</button>`;if(cap('ccoQs')&&['SENT_TO_QS','QS_PRICING','RAB_READY'].includes(s))x+=`<button class="btn small" data-cco-doc="rab" data-id="${esc(r.id)}">Upload RAB</button>`;if(cap('ccoEscalation')&&s==='RAB_READY'&&num(r.data.percentOfRab)>10&&!r.data.sopEscalationApproved)x+=`<button class="btn small warning" data-cco-action="approve-escalation" data-id="${esc(r.id)}">Approve Eskalasi</button>`;if(cap('ccoAdmin')&&s==='RAB_READY')x+=`<button class="btn small primary" data-cco-action="send-client" data-id="${esc(r.id)}">Kirim ke Client</button>`;if(cap('ccoAdmin')&&s==='SENT_TO_CLIENT')x+=`<button class="btn small success" data-cco-action="client-approve" data-id="${esc(r.id)}">Client Setuju</button><button class="btn small danger" data-cco-action="client-reject" data-id="${esc(r.id)}">Client Tolak</button>`;if(cap('ccoAdmin')&&s==='CLIENT_APPROVED')x+=`<button class="btn small primary" data-cco-action="start-addendum" data-id="${esc(r.id)}">Proses Addendum</button>`;if(cap('ccoAdmin')&&['CLIENT_APPROVED','ADDENDUM_PROCESS'].includes(s))x+=`<button class="btn small" data-cco-doc="addendum" data-id="${esc(r.id)}">Upload Addendum</button><button class="btn small success" data-cco-action="close" data-id="${esc(r.id)}">Close</button>`;if((cap('ccoAdmin')||cap('ccoQs'))&&!['DRAFT','RETURNED_TO_FIELD','CLOSED','CLIENT_APPROVED','ADDENDUM_PROCESS'].includes(s))x+=`<button class="btn small" data-cco-action="return-field" data-id="${esc(r.id)}">Kembalikan</button>`;return x||'-';}
function openCcoPricing(id){const rows=state.cache.get(`cco|${state.selectedProjectId}`)||state.cache.get('cco|')||[];const r=rows.find(x=>x.id===id);const html=`<div class="form-grid"><label>Nilai RAB CCO<input type="number" step="any" name="amount" value="${esc(r?.data?.amount||'')}" required></label><label>No./Referensi RAB<input name="rabNumber" value="${esc(r?.data?.rabNumber||'')}"></label><label class="span-2">Catatan QS<textarea name="notes">${esc(r?.data?.rabNotes||'')}</textarea></label><label class="span-2">Upload RAB CCO (opsional di langkah ini)<input type="file" name="file"></label></div>`;openModal('Finalisasi RAB CCO','% terhadap RAB proyek dihitung otomatis oleh sistem.',html,async form=>{await api(`/api/cco/${encodeURIComponent(id)}/action`,{method:'POST',body:{action:'complete-pricing',amount:Number(form.amount.value),rabNumber:form.rabNumber.value,notes:form.notes.value}});const file=form.file.files[0];if(file){const rec=r||{data:{projectId:state.selectedProjectId,title:'CCO'}};await uploadRelatedDocument(file,{projectId:rec.data.projectId,category:'CCO_RAB',title:`RAB CCO - ${rec.data.title||id}`,relatedCollection:'cco',relatedId:id});}toast('RAB CCO selesai dan tahap diperbarui.');state.cache.clear();await renderCco();});}

async function renderProcurement(){const [prs,pos]=await Promise.all([loadCollection('procurement',Boolean(state.selectedProjectId)),loadCollection('po',Boolean(state.selectedProjectId))]);$('#content').innerHTML=`<div class="info-grid"><div class="info-card"><span class="tag manual">Form 1</span><h4>PR / Purchase Request</h4><p>Permintaan internal dari Pelaksana/PM/Logistik: item apa, jumlah, estimasi budget, kapan dibutuhkan. PR belum berarti vendor sudah dipesan dan belum otomatis menjadi Cash Out.</p></div><div class="info-card"><span class="tag auto">Form 2</span><h4>PO / SPK</h4><p>Dokumen komitmen resmi ke vendor/subkon setelah PR disetujui. Saat PO/SPK Approved/Ordered, sistem otomatis membentuk Hutang/Outstanding. Pembayaran tetap dicatat terpisah.</p></div></div><div class="card"><div class="card-head"><div><h3>Purchase Request (PR)</h3><p>Permintaan kebutuhan sebelum pemesanan.</p></div>${canCollection('procurement','create')?'<div class="card-actions"><button class="btn primary" data-add="procurement">+ Buat PR</button></div>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Proyek</th><th>Requester</th><th>Item</th><th>Qty</th><th>Estimasi</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${prs.map(r=>`<tr><td>${fmtDate(r.data.date)}</td><td>${esc(projectName(r.data.projectId))}</td><td>${esc(employeeName(r.data.requesterUserId))}</td><td>${esc(r.data.item||'-')}</td><td>${fmtNum(r.data.qty)} ${esc(r.data.unit||'')}</td><td class="num">${fmtRp(r.data.budgetAmount)}</td><td>${statusPill(r.data.status||'DRAFT')}</td><td class="actions">${prButtons(r)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">Belum ada PR.</td></tr>'}</tbody></table></div></div>${poTable(pos)}`;bindCrudActions();bindWorkflowButtons();}
function prButtons(r){const s=String(r.data.status||'DRAFT').toUpperCase();let x='';if(canCollection('procurement','update')&&['DRAFT','REJECTED'].includes(s))x+=`<button class="btn small" data-edit="procurement" data-id="${esc(r.id)}">Edit</button>`;if(['DRAFT','REJECTED'].includes(s))x+=`<button class="btn small primary" data-pr-action="submit" data-id="${esc(r.id)}">Submit</button>`;if(cap('procurementApprove')&&s==='SUBMITTED')x+=`<button class="btn small success" data-pr-action="approve" data-id="${esc(r.id)}">Approve</button><button class="btn small danger" data-pr-action="reject" data-id="${esc(r.id)}">Reject</button>`;if(canCollection('po','create')&&s==='APPROVED')x+=`<button class="btn small accent" data-create-po="${esc(r.id)}">Buat PO/SPK</button>`;if(cap('procurementOrder')&&s==='APPROVED')x+=`<button class="btn small" data-pr-action="order" data-id="${esc(r.id)}">Tandai Ordered</button>`;if(cap('procurementOrder')&&s==='ORDERED')x+=`<button class="btn small success" data-pr-action="receive" data-id="${esc(r.id)}">Material Diterima</button>`;return x||'-';}
function poTable(rows){return `<div class="card"><div class="card-head"><div><h3>PO / SPK</h3><p>Komitmen resmi; Approved/Ordered masuk committed cost/hutang.</p></div>${canCollection('po','create')?'<div class="card-actions"><button class="btn primary" data-add="po">+ PO/SPK</button></div>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>No.</th><th>PR</th><th>Proyek</th><th>Vendor</th><th>Deskripsi</th><th>Nilai</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.data.number||r.id)}</td><td>${esc(r.data.prId||'-')}</td><td>${esc(projectName(r.data.projectId))}</td><td>${esc(r.data.vendor||'-')}</td><td>${esc(r.data.description||'-')}</td><td class="num">${fmtRp(r.data.amount)}</td><td>${statusPill(r.data.status||'DRAFT')}</td><td class="actions">${canCollection('po','update')?`<button class="btn small" data-edit="po" data-id="${esc(r.id)}">Edit</button>`:''}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">Belum ada PO/SPK.</td></tr>'}</tbody></table></div></div>`;}
function openPoFromPr(prId){const rows=state.cache.get(`procurement|${state.selectedProjectId}`)||state.cache.get('procurement|')||[];const r=rows.find(x=>x.id===prId);openRecordForm('po',null,{projectId:r?.data.projectId||state.selectedProjectId,prId,description:r?.data.item||'',amount:r?.data.budgetAmount||'',date:new Date().toISOString().slice(0,10),status:'DRAFT'});}

async function renderDocuments(){const q=state.selectedProjectId?`?projectId=${encodeURIComponent(state.selectedProjectId)}`:'';const r=await api('/api/documents'+q);const rows=r.documents||[];$('#content').innerHTML=`<div class="card"><div class="card-head"><div><h3>Dokumen Proyek</h3><p>File tersimpan di R2 dan metadata di D1.</p></div>${canCollection('project_documents','create')?'<div class="card-actions"><button class="btn primary" id="uploadDoc">+ Upload Dokumen</button></div>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Proyek</th><th>Kategori</th><th>Judul</th><th>Versi</th><th>File</th><th>Relasi</th><th>Aksi</th></tr></thead><tbody>${rows.map(d=>`<tr><td>${esc(projectName(d.data.projectId))}</td><td>${statusPill(d.data.category)}</td><td>${esc(d.data.title||d.data.originalName||'-')}</td><td>v${fmtNum(d.data.version||1,0)}</td><td>${esc(d.data.originalName||'-')}</td><td>${esc(d.data.relatedCollection||'-')} ${esc(d.data.relatedId||'')}</td><td class="actions"><button class="btn small" data-doc-open="${esc(d.id)}">Buka</button>${canCollection('project_documents','update')?`<button class="btn small" data-doc-edit="${esc(d.id)}">Edit/Ganti</button>`:''}${canCollection('project_documents','delete')?`<button class="btn small danger" data-doc-delete="${esc(d.id)}">Hapus</button>`:''}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Belum ada dokumen.</td></tr>'}</tbody></table></div></div>`;if($('#uploadDoc'))$('#uploadDoc').onclick=()=>openDocumentForm(null,{projectId:state.selectedProjectId});$$('[data-doc-open]').forEach(b=>b.onclick=()=>window.open(`/api/documents/${encodeURIComponent(b.dataset.docOpen)}/file`,'_blank'));$$('[data-doc-edit]').forEach(b=>b.onclick=()=>openDocumentForm(rows.find(x=>x.id===b.dataset.docEdit)));$$('[data-doc-delete]').forEach(b=>b.onclick=async()=>{if(await confirmAsk('Hapus dokumen ini? File R2 juga akan dihapus.')){await api(`/api/documents/${encodeURIComponent(b.dataset.docDelete)}`,{method:'DELETE'});toast('Dokumen dihapus');await renderDocuments();}});}

async function renderFlow(){if(!state.selectedProjectId){$('#content').innerHTML=noProjectPrompt('Pilih satu proyek untuk melihat gate lengkap.');bindGotoProjects();return;}const r=await api(`/api/projects/${encodeURIComponent(state.selectedProjectId)}/flow`);const e=r.evaluation;$('#content').innerHTML=`<div class="kpis">${kpi('Gate Aktif',esc(e.gate),'purple')}${kpi('Progress',`${fmtNum(e.metrics.progress)}%`,'blue')}${kpi('QC Open',fmtNum(e.metrics.openQc,0),'orange')}${kpi('Defect Open',fmtNum(e.metrics.openDefects,0),'red')}${kpi('CCO Pending',fmtNum(e.metrics.pendingCco,0),'orange')}${kpi('Status',esc(e.status),e.status==='CLOSED'?'green':'orange')}</div><div class="flow-strip">${e.flow.map(x=>`<div class="flow-step ${x.done?'done':(x.code===e.status?'current':'')}"><b>${esc(x.label)}</b>${x.done?'✓ Selesai':x.code===e.status?'Sedang berjalan':'Belum'}</div>`).join('')}</div><div class="card"><div class="card-head"><div><h3>Blocker Saat Ini</h3><p>Project CLOSED hanya jika semua gate selesai.</p></div>${canCollection('projects','update')?'<div class="card-actions"><button id="syncProject" class="btn primary">Evaluasi & Sync Status</button></div>':''}</div><div class="card-body">${e.blockers.length?`<ul class="blockers">${e.blockers.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<span class="pill green">Tidak ada blocker</span>'}</div></div>`;if($('#syncProject'))$('#syncProject').onclick=async()=>{await api(`/api/projects/${encodeURIComponent(state.selectedProjectId)}/sync-status`,{method:'POST'});toast('Status proyek disinkronkan');await fullRefresh();setView('flow');};}

async function renderCloseout(){if(!state.selectedProjectId){$('#content').innerHTML=noProjectPrompt('Pilih satu proyek untuk close-out.');bindGotoProjects();return;}const [flow,ret,cl]=await Promise.all([api(`/api/projects/${encodeURIComponent(state.selectedProjectId)}/flow`),loadCollection('retention',true),loadCollection('closeout',true)]);const e=flow.evaluation;$('#content').innerHTML=`<div class="card"><div class="card-head"><div><h3>Close-Out Readiness</h3><p>100% fisik belum berarti Closed.</p></div><div class="card-actions">${canCollection('closeout','create')?'<button class="btn ghost" id="coGenerate">Buat Checklist Standar</button>':''}${canCollection('project_documents','create')?'<button class="btn accent" id="coUpload">Upload Dokumen</button>':''}${canCollection('projects','update')?'<button class="btn primary" id="coSync">Evaluasi & Sync</button>':''}</div></div><div class="card-body">${e.blockers.length?`<ul class="blockers">${e.blockers.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<span class="pill green">Siap CLOSED</span>'}</div></div>${genericTable('retention',ret,'Retensi / Masa Pemeliharaan','')}${genericTable('closeout',cl,'Checklist Close-Out','')}`;bindCrudActions();if($('#coGenerate'))$('#coGenerate').onclick=generateCloseout;if($('#coUpload'))$('#coUpload').onclick=()=>openDocumentForm(null,{projectId:state.selectedProjectId});if($('#coSync'))$('#coSync').onclick=async()=>{await api(`/api/projects/${encodeURIComponent(state.selectedProjectId)}/sync-status`,{method:'POST'});toast('Status disinkronkan');await fullRefresh();setView('closeout');};}
async function generateCloseout(){const items=['Final QC dan defect telah ditutup','BAST / PHO lengkap','As-built drawing lengkap','Retensi / masa pemeliharaan selesai bila berlaku','FHO lengkap bila diwajibkan','Seluruh CCO / addendum selesai','Piutang client diselesaikan','Hutang vendor/tukang/subkon diselesaikan','Final reconciliation selesai','Arsip proyek lengkap'];const existing=await loadCollection('closeout',true);const set=new Set(existing.map(x=>String(x.data.item||'').toLowerCase()));let n=0;for(const item of items){if(set.has(item.toLowerCase()))continue;await api('/api/records/closeout',{method:'POST',body:{id:crypto.randomUUID(),data:{projectId:state.selectedProjectId,item,status:'OPEN'}}});n++;}toast(`${n} checklist baru dibuat`);state.cache.clear();await renderCloseout();}

async function renderEmployees(){
  if(!cap('manageEmployees')){$('#content').innerHTML='<div class="notice">Hanya Administrator/Direktur/Head Unit Bisnis yang dapat mengelola karyawan dan akses.</div>';return;}
  const r=await api('/api/records/users');const rows=r.rows||[];
  const matrix=[['Administrator / Direktur / Head Unit','Akses penuh termasuk karyawan, role, keuangan, audit.'],['Manager Operasional','Kontrol operasional lintas proyek, QC, CCO, opname, PR, monitoring finance.'],['Admin Teknik','Administrasi proyek, dokumen, CCO routing, approval administratif.'],['Project Manager','Progress, issue, QC monitoring, CCO, PR, pengajuan dana proyek.'],['Pelaksana Lapangan','Progress, QC lapangan, pengajuan CCO, PR, dan pengajuan dana.'],['QS','Opname/volume, RAB/CCO pricing, dokumen komersial.'],['QC','Checklist pekerjaan, inspeksi, upload bukti, defect/re-inspection.'],['Finance','Piutang, Cash In, hutang, Cash Out, approval/bayar pengajuan dana.'],['Logistik / Procurement','PR, PO/SPK, vendor, delivery.'],['Viewer','Baca dashboard/proyek/dokumen/alur saja.']];
  $('#content').innerHTML=`<div class="role-matrix">${matrix.map(x=>`<div class="role-card"><h4>${esc(x[0])}</h4><p>${esc(x[1])}</p></div>`).join('')}</div><div class="card" style="margin-top:16px"><div class="card-head"><div><h3>Karyawan & Akun Login</h3><p>Nama pada form proyek/PIC berasal dari daftar ini.</p></div><div class="card-actions"><button class="btn primary" id="addEmployee">+ Tambah Karyawan</button></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Nama</th><th>Username</th><th>Role</th><th>Jabatan</th><th>Unit/Departemen</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${rows.map(u=>`<tr><td><b>${esc(u.data.name||u.data.username||u.id)}</b><div class="tiny muted">${esc(u.data.email||'')}</div></td><td>${esc(u.data.username||u.id)}</td><td>${statusPill(u.data.role||'-')}</td><td>${esc(u.data.jabatan||'-')}</td><td>${esc([u.data.unit,u.data.departemen].filter(Boolean).join(' / ')||'-')}</td><td>${statusPill(u.data.status||'Aktif')}</td><td class="actions"><button class="btn small" data-employee-edit="${esc(u.id)}">Edit</button><button class="btn small danger" data-employee-delete="${esc(u.id)}">Hapus</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Belum ada karyawan.</td></tr>'}</tbody></table></div></div>`;
  $('#addEmployee').onclick=()=>openEmployeeForm();$$('[data-employee-edit]').forEach(b=>b.onclick=()=>openEmployeeForm(rows.find(x=>x.id===b.dataset.employeeEdit)));$$('[data-employee-delete]').forEach(b=>b.onclick=async()=>{if(await confirmAsk('Hapus akun karyawan ini?')){await api(`/api/records/users/${encodeURIComponent(b.dataset.employeeDelete)}`,{method:'DELETE'});toast('Karyawan dihapus');await fullRefresh();setView('employees');}});
}
function openEmployeeForm(row=null){const d=row?.data||{};const html=`<div class="form-grid"><label>Nama Lengkap<input name="name" value="${esc(d.name||'')}" required></label><label>Username<input name="username" value="${esc(d.username||'')}" required></label><label>Email<input type="email" name="email" value="${esc(d.email||'')}"></label><label>No. HP<input name="phone" value="${esc(d.phone||'')}"></label><label>Role<select name="role" required><option value="">Pilih role</option>${ROLES.map(x=>`<option ${x===(d.role||'')?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Jabatan<input name="jabatan" value="${esc(d.jabatan||'')}"></label><label>Unit<input name="unit" value="${esc(d.unit||'Natara Konstruksi')}"></label><label>Departemen<input name="departemen" value="${esc(d.departemen||'')}"></label><label>Status<select name="status"><option ${String(d.status||'Aktif')==='Aktif'?'selected':''}>Aktif</option><option ${String(d.status||'')==='Nonaktif'?'selected':''}>Nonaktif</option></select></label><label>Password ${row?'<span class="field-help">Kosongkan jika tidak ingin mengganti.</span>':'<span class="field-help">Minimal 6 karakter.</span>'}<input type="password" name="password" ${row?'':'required minlength="6"'}></label></div>`;openModal(row?'Edit Karyawan':'Tambah Karyawan','Role menentukan menu dan API yang dapat dibuka.',html,async form=>{const data={};for(const k of ['name','username','email','phone','role','jabatan','unit','departemen','status','password'])data[k]=form.elements[k].value;const id=row?.id||data.username||crypto.randomUUID();if(row)await api(`/api/records/users/${encodeURIComponent(id)}`,{method:'PUT',body:data});else await api('/api/records/users',{method:'POST',body:{id,data}});toast('Data karyawan disimpan');await fullRefresh();setView('employees');});}

async function renderMaster(){const names=['rabs','surat','vendor','tukang','aset','pelatihan','proyeksi'].filter(c=>canCollection(c,'read'));const rows=await Promise.all(names.map(c=>loadCollection(c,Boolean(state.selectedProjectId)&&['rabs','surat','proyeksi'].includes(c))));$('#content').innerHTML=`<div class="notice blue">Master Karyawan dipisahkan ke menu <b>Karyawan & Akses</b> agar role dan login lebih jelas.</div>`+names.map((c,i)=>genericTable(c,rows[i],configs[c]?.label||c,'')).join('');bindCrudActions();}
async function renderAudit(){const q=state.selectedProjectId?`?projectId=${encodeURIComponent(state.selectedProjectId)}&limit=300`:'?limit=300';const r=await api('/api/audit'+q);const logs=r.logs||[];$('#content').innerHTML=`<div class="card"><div class="card-head"><div><h3>Audit Log</h3><p>Jejak perubahan penting dan workflow.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Waktu</th><th>User</th><th>Aksi</th><th>Collection</th><th>Proyek</th><th>Record</th></tr></thead><tbody>${logs.map(x=>`<tr><td>${fmtDate(x.created_at)}</td><td>${esc(x.actor_name||x.actor_id)}</td><td>${statusPill(x.action)}</td><td>${esc(x.collection)}</td><td>${esc(projectName(x.project_id))}</td><td>${esc(x.record_id)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Belum ada audit log.</td></tr>'}</tbody></table></div></div>`;}

function genericTable(collection,rows,title,desc=''){const cfg=configs[collection]||{label:collection};return `<div class="card"><div class="card-head"><div><h3>${esc(title||cfg.label)}</h3><p>${esc(desc)}</p></div>${canCollection(collection,'create')?`<div class="card-actions"><button class="btn primary" data-add="${esc(collection)}">+ Tambah</button></div>`:''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal/ID</th><th>Proyek</th><th>Uraian</th><th>PIC/Pihak</th><th>Nilai/Progress</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(r=>genericRow(collection,r)).join('')||'<tr><td colspan="7" class="empty">Belum ada data.</td></tr>'}</tbody></table></div></div>`;}
function genericRow(c,r){const d=r.data||{};const date=d.date||d.startDate||d.dueDate||d.plannedDate||d.createdAt||r.updated_at;const title=d.description||d.item||d.name||d.workItem||d.activity||d.problem||d.subject||d.title||d.category||r.id;const person=d.picUserId||d.qsUserId||d.ownerUserId||d.requesterUserId;let val='-';if(d.amount!==undefined)val=fmtRp(d.amount);else if(d.budgetAmount!==undefined)val=fmtRp(d.budgetAmount);else if(d.progress!==undefined)val=`${fmtNum(d.progress)}%`;else if(d.verifiedVolume!==undefined)val=fmtNum(d.verifiedVolume);const status=d.status||d.result||'-';return `<tr><td>${fmtDate(date)}<div class="tiny muted">${esc(r.id)}</div></td><td>${d.projectId?esc(projectName(d.projectId)):'-'}</td><td>${esc(title||'-')}</td><td>${person?esc(employeeName(person)):esc(d.vendor||d.participant||'-')}</td><td class="num">${val}</td><td>${statusPill(status)}</td><td class="actions">${canCollection(c,'update')?`<button class="btn small" data-edit="${esc(c)}" data-id="${esc(r.id)}">Edit</button>`:''}${canCollection(c,'delete')?`<button class="btn small danger" data-delete="${esc(c)}" data-id="${esc(r.id)}">Hapus</button>`:''}</td></tr>`;}

function bindCrudActions(){
  $$('[data-add]').forEach(b=>b.onclick=()=>openRecordForm(b.dataset.add));
  $$('[data-edit]').forEach(b=>b.onclick=async()=>{const c=b.dataset.edit;let rows=state.cache.get(`${c}|${state.selectedProjectId}`)||state.cache.get(`${c}|`);if(!rows)rows=await loadCollection(c,Boolean(state.selectedProjectId));const row=rows.find(x=>x.id===b.dataset.id);openRecordForm(c,row);});
  $$('[data-delete]').forEach(b=>b.onclick=async()=>{if(await confirmAsk('Hapus data ini?')){await api(`/api/records/${encodeURIComponent(b.dataset.delete)}/${encodeURIComponent(b.dataset.id)}`,{method:'DELETE'});toast('Data dihapus');await refreshAfterMutation();}});
  $$('[data-create-po]').forEach(b=>b.onclick=()=>openPoFromPr(b.dataset.createPo));
}
function bindWorkflowButtons(){
  $$('[data-fund-action]').forEach(b=>b.onclick=()=>fundAction(b.dataset.id,b.dataset.fundAction));
  $$('[data-pr-action]').forEach(b=>b.onclick=()=>simpleAction(`/api/procurement/${encodeURIComponent(b.dataset.id)}/action`,b.dataset.prAction));
  $$('[data-cco-action]').forEach(b=>b.onclick=()=>ccoAction(b.dataset.id,b.dataset.ccoAction));
  $$('[data-cco-price]').forEach(b=>b.onclick=()=>openCcoPricing(b.dataset.ccoPrice));
  $$('[data-cco-doc]').forEach(b=>b.onclick=async()=>{const id=b.dataset.id;const rows=state.cache.get(`cco|${state.selectedProjectId}`)||state.cache.get('cco|')||[];const r=rows.find(x=>x.id===id);openDocumentForm(null,{projectId:r?.data.projectId||state.selectedProjectId,category:b.dataset.ccoDoc==='rab'?'CCO_RAB':'CCO_ADDENDUM',title:`${b.dataset.ccoDoc==='rab'?'RAB CCO':'Addendum CCO'} - ${r?.data.title||id}`,relatedCollection:'cco',relatedId:id});});
}
async function simpleAction(path,action,extra={}){try{await api(path,{method:'POST',body:{action,...extra}});toast('Workflow diperbarui');state.cache.clear();await renderView();}catch(err){toast(err.message,'err');}}
async function fundAction(id,action){if(action==='pay'){const html=`<div class="form-grid"><label>Tanggal Bayar<input type="date" name="paymentDate" value="${new Date().toISOString().slice(0,10)}" required></label><label>Rekening/Metode<input name="account"></label><label class="span-2">Referensi Pembayaran<input name="reference"></label></div>`;openModal('Bayar Pengajuan','Setelah disimpan, Cash Out dibuat otomatis.',html,async form=>{await api(`/api/payment-requests/${encodeURIComponent(id)}/action`,{method:'POST',body:{action:'pay',paymentDate:form.paymentDate.value,account:form.account.value,reference:form.reference.value}});toast('Pengajuan dibayar dan Cash Out dibuat otomatis.');state.cache.clear();await renderFundRequests();});return;}if(action==='reject'){const note=prompt('Alasan penolakan:')||'';return simpleAction(`/api/payment-requests/${encodeURIComponent(id)}/action`,'reject',{notes:note});}return simpleAction(`/api/payment-requests/${encodeURIComponent(id)}/action`,action);}
async function ccoAction(id,action){let extra={};if(['client-reject','return-field'].includes(action))extra.notes=prompt('Catatan/alasan:')||'';if(action==='close'&&!await confirmAsk('Close CCO? Sistem akan memeriksa Addendum final sudah di-upload.'))return;return simpleAction(`/api/cco/${encodeURIComponent(id)}/action`,action,extra);}

function fieldHtml(field,value){
  const req=field.required?'required':'';const cls=field.cls||'';const help=field.help?`<span class="field-help">${esc(field.help)}</span>`:'';
  if(field.type==='project'){const val=value||state.selectedProjectId||'';return `<label class="${cls}">${esc(field.label)}<select name="${field.name}" ${req}><option value="">Pilih proyek</option>${state.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===val?'selected':''}>${esc(p.data.name||p.id)}</option>`).join('')}</select>${help}</label>`;}
  if(field.type==='employee'){const roles=field.roles||[];const opts=state.employees.filter(e=>!roles.length||roles.includes(e.roleKey));return `<label class="${cls}">${esc(field.label)}<select name="${field.name}" ${req}><option value="">Pilih karyawan</option>${opts.map(e=>`<option value="${esc(e.id)}" ${e.id===value?'selected':''}>${esc(e.name)} — ${esc(e.jabatan||e.role)}</option>`).join('')}</select>${help}</label>`;}
  if(field.type==='select')return `<label class="${cls}">${esc(field.label)}<select name="${field.name}" ${req}><option value="">Pilih</option>${(field.options||[]).map(o=>`<option value="${esc(o)}" ${String(value??'')===String(o)?'selected':''}>${esc(o)}</option>`).join('')}</select>${help}</label>`;
  if(field.type==='textarea')return `<label class="${cls}">${esc(field.label)}<textarea name="${field.name}" ${req}>${esc(value||'')}</textarea>${help}</label>`;
  if(field.type==='checkbox')return `<label class="check ${cls}"><input type="checkbox" name="${field.name}" ${value?'checked':''}/> ${esc(field.label)}</label>`;
  return `<label class="${cls}">${esc(field.label)}<input name="${field.name}" type="${field.type}" value="${esc(value??'')}" ${req}${field.type==='number'?' step="any"':''}>${help}</label>`;
}
function formDataFromFields(form,fields){const data={};for(const field of fields){const el=form.elements[field.name];if(!el)continue;if(field.type==='checkbox')data[field.name]=el.checked;else if(field.type==='number')data[field.name]=el.value===''?'':Number(el.value);else data[field.name]=el.value;}return data;}
function openRecordForm(collection,row=null,preset={}){const cfg=configs[collection];if(!cfg){toast(`Form ${collection} belum tersedia.`,'err');return;}const data={...preset,...(row?.data||{})};if(!row&&collection==='projects'&&data.qcRequired===undefined)data.qcRequired=true;if(!row&&['payment_requests','procurement'].includes(collection)&&!data.requesterUserId)data.requesterUserId=state.user.id;if(!row&&collection==='cco'&&!data.requestedByUserId)data.requestedByUserId=state.user.id;if(!row&&collection==='daily_progress'&&!data.picUserId)data.picUserId=state.user.id;const html=`<div class="form-grid">${cfg.fields.map(x=>fieldHtml(x,data[x.name])).join('')}${cfg.attachment?`<label class="span-2">Lampiran pendukung (opsional)<input type="file" name="attachment"></label>`:''}</div>`;openModal(`${row?'Edit':'Tambah'} ${cfg.label}`,cfg.attachment?'Lampiran otomatis masuk Dokumen Proyek. Untuk QC Inspection, bukti wajib memakai form QC khusus.':'',html,async form=>{const payload=formDataFromFields(form,cfg.fields);const file=form.elements.attachment?.files?.[0];const id=row?.id||crypto.randomUUID();if(row)await api(`/api/records/${collection}/${encodeURIComponent(id)}`,{method:'PUT',body:payload});else await api(`/api/records/${collection}`,{method:'POST',body:{id,data:payload}});if(file){if(!(payload.projectId||state.selectedProjectId))throw new Error('Lampiran harus terkait proyek.');await uploadRelatedDocument(file,{projectId:payload.projectId||state.selectedProjectId,category:cfg.docCategory||'OTHER',title:`${cfg.label} - ${payload.title||payload.description||payload.item||payload.name||id}`,relatedCollection:collection,relatedId:id});}toast('Data disimpan');await refreshAfterMutation();});}
async function uploadRelatedDocument(file,meta){const fd=new FormData();fd.append('file',file);for(const [k,v] of Object.entries(meta))fd.append(k,String(v??''));return api('/api/documents',{method:'POST',body:fd});}
function openDocumentForm(row=null,preset={}){const d=row?.data||preset;const html=`<div class="form-grid"><label>Proyek<select name="projectId" required><option value="">Pilih proyek</option>${state.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===(d.projectId||state.selectedProjectId)?'selected':''}>${esc(p.data.name||p.id)}</option>`).join('')}</select></label><label>Kategori<select name="category" required>${DOC_CATEGORIES.map(x=>`<option value="${x}" ${x===(d.category||'OTHER')?'selected':''}>${x}</option>`).join('')}</select></label><label class="span-2">Judul<input name="title" required value="${esc(d.title||d.originalName||'')}"></label><label class="span-2">Catatan<textarea name="notes">${esc(d.notes||'')}</textarea></label><input type="hidden" name="relatedCollection" value="${esc(d.relatedCollection||'')}"><input type="hidden" name="relatedId" value="${esc(d.relatedId||'')}"><label class="span-2">${row?'Ganti file (opsional)':'File'}<input type="file" name="file" ${row?'':'required'}></label></div>`;openModal(row?'Edit / Ganti Dokumen':'Upload Dokumen','File baru menggantikan file aktif pada dokumen yang sama.',html,async form=>{const fd=new FormData();for(const k of ['projectId','category','title','notes','relatedCollection','relatedId'])fd.append(k,form.elements[k].value);const file=form.elements.file.files[0];if(file)fd.append('file',file);if(row)await api(`/api/documents/${encodeURIComponent(row.id)}`,{method:'PUT',body:fd});else await api('/api/documents',{method:'POST',body:fd});toast('Dokumen disimpan');state.cache.clear();await renderView();});}
function openPasswordForm(){const html=`<div class="form-grid"><label class="span-2">Password Saat Ini<input type="password" name="oldPassword" required></label><label class="span-2">Password Baru<input type="password" name="newPassword" minlength="6" required></label></div>`;openModal('Ganti Password','Minimal 6 karakter.',html,async form=>{await api('/api/auth/change-password',{method:'POST',body:{oldPassword:form.oldPassword.value,newPassword:form.newPassword.value}});toast('Password diperbarui');});}
function openModal(title,hint,html,onSubmit){state.modal={onSubmit};$('#modalTitle').textContent=title;$('#modalHint').textContent=hint||'';$('#modalForm').innerHTML=html;$('#modalBackdrop').classList.remove('hidden');$('#modalForm').onsubmit=async e=>{e.preventDefault();try{await state.modal.onSubmit(e.currentTarget);closeModal();}catch(err){toast(err.message,'err');}};}
function closeModal(){$('#modalBackdrop').classList.add('hidden');state.modal=null;}
function confirmAsk(text){$('#confirmText').textContent=text;$('#confirmBackdrop').classList.remove('hidden');return new Promise(resolve=>state.confirmResolve=resolve);}
function resolveConfirm(v){$('#confirmBackdrop').classList.add('hidden');state.confirmResolve?.(v);state.confirmResolve=null;}
function noProjectPrompt(text){return `<div class="card"><div class="card-body empty">${esc(text)}<br><br><button class="btn primary" id="gotoProjects">Buka Daftar Proyek</button></div></div>`;}
function bindGotoProjects(){if($('#gotoProjects'))$('#gotoProjects').onclick=()=>setView('projects');}
async function refreshAfterMutation(){state.cache.clear();const [p,d,e]=await Promise.all([api('/api/records/projects'),api('/api/dashboard'),api('/api/employees')]);state.projects=p.rows||[];state.dashboard=d;state.employees=e.employees||[];populateProjectFilter();await renderView();}

init();
